import math

def log_decrement_damping_ratio(x1: float, xn: float, n: float) -> float:
    delta = (1.0 / n) * math.log(x1 / xn)
    zeta = delta / math.sqrt(4 * math.pi**2 + delta**2)
    return round(zeta, 5)

import math

def principal_inertia(Ixx: float, Iyy: float, Ixy: float) -> tuple[float, float]:
    avg = (Ixx + Iyy) / 2.0
    diff = (Ixx - Iyy) / 2.0
    R = math.sqrt(diff**2 + Ixy**2)
    return (round(avg + R, 4), round(avg - R, 4))
